CREATE TABLE ad_account(account_id UUID PRIMARY KEY);
CREATE TABLE ad_campaign(id UUID PRIMARY KEY,name VARCHAR(120) NOT NULL,country CHAR(2) NOT NULL,maturity INTEGER NOT NULL CHECK(maturity BETWEEN 0 AND 18),placement VARCHAR(12) NOT NULL CHECK(placement IN('PRE_ROLL','MID_ROLL','POST_ROLL')),starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL CHECK(ends_at>starts_at),daily_cap INTEGER NOT NULL CHECK(daily_cap BETWEEN 1 AND 20),creative_url VARCHAR(2048) NOT NULL,duration_millis INTEGER NOT NULL CHECK(duration_millis BETWEEN 1000 AND 120000),enabled BOOLEAN NOT NULL DEFAULT true,version BIGINT NOT NULL DEFAULT 1 CHECK(version>0));
CREATE INDEX ad_campaign_eligibility ON ad_campaign(country,placement,starts_at,id) WHERE enabled;
CREATE TABLE ad_decision(id UUID PRIMARY KEY,account_id UUID NOT NULL REFERENCES ad_account(account_id),profile_id UUID NOT NULL,device_id UUID NOT NULL,session_id UUID NOT NULL,campaign_id UUID NOT NULL REFERENCES ad_campaign(id),idempotency_key VARCHAR(128) NOT NULL,fingerprint CHAR(64) NOT NULL,window_day DATE NOT NULL,adapter VARCHAR(8) NOT NULL CHECK(adapter IN('CSAI','SSAI')),state VARCHAR(8) NOT NULL CHECK(state IN('PENDING','ACTIVE','SKIPPED')),expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL,issued_at TIMESTAMPTZ,claim_token UUID,claimed_until TIMESTAMPTZ,media_url VARCHAR(2048),duration_millis INTEGER NOT NULL,version BIGINT NOT NULL DEFAULT 0,UNIQUE(account_id,idempotency_key));
CREATE INDEX ad_cap_lookup ON ad_decision(account_id,campaign_id,window_day,state);
CREATE TABLE ad_receipt(event_id UUID PRIMARY KEY,account_id UUID NOT NULL,fingerprint CHAR(64) NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ad_event(decision_id UUID NOT NULL REFERENCES ad_decision(id),quartile INTEGER NOT NULL CHECK(quartile BETWEEN 0 AND 4),occurred_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(decision_id,quartile));
CREATE TABLE ad_audit(id UUID PRIMARY KEY,campaign_id UUID NOT NULL REFERENCES ad_campaign(id),actor_hash CHAR(64) NOT NULL,action VARCHAR(40) NOT NULL,version BIGINT NOT NULL,at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE outbox_event(event_id UUID PRIMARY KEY,aggregate_id UUID NOT NULL,aggregate_version BIGINT NOT NULL,topic VARCHAR(120) NOT NULL,payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at TIMESTAMPTZ,claim_token UUID,claimed_until TIMESTAMPTZ,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX engagement_outbox_pending_idx ON outbox_event(next_attempt_at,created_at,event_id) WHERE published_at IS NULL;
